def rle(s):
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for char in s[1:]:
        if char == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = char
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)

def balanced(s):
    """
    Returns True if brackets (), [], {} in s are correctly nested and closed.
    Other characters are ignored.
    """
    stack = []
    brackets = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in brackets.values():
            stack.append(char)
        elif char in brackets:
            if not stack or stack.pop() != brackets[char]:
                return False
    return not stack

def to_base(n, b):
    """
    Convert a non-negative integer n to a string in base b (2..16).
    Uses lowercase digits for values 10-15.
    """
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result = []
    while n > 0:
        n, remainder = divmod(n, b)
        result.append(digits[remainder])
    return ''.join(reversed(result))
